-- Schema migrations: MergeTree family DDL, TTL, codecs, projections, indices
CREATE TABLE events (ts DateTime, user_id UInt64, name String) ENGINE = MergeTree ORDER BY (user_id, ts);
CREATE TABLE IF NOT EXISTS default.events2 (ts DateTime, user_id UInt64, name LowCardinality(String), props Map(String, String)) ENGINE = MergeTree PARTITION BY toYYYYMM(ts) ORDER BY (name, user_id, ts) SETTINGS index_granularity = 8192;
CREATE TABLE web_events (ts DateTime64(3) CODEC(Delta, ZSTD(1)), user_id UInt64, session_id UUID, url String, country LowCardinality(String), tags Array(String), amount Nullable(Decimal(18, 4)), ua Tuple(browser String, os String)) ENGINE = MergeTree PARTITION BY toDate(ts) ORDER BY (country, user_id, ts) TTL toDateTime(ts) + INTERVAL 90 DAY DELETE SETTINGS index_granularity = 8192;
CREATE TABLE metrics (ts DateTime, host LowCardinality(String), value Float64) ENGINE = MergeTree ORDER BY (host, ts) TTL ts + INTERVAL 1 MONTH TO VOLUME 'cold', ts + INTERVAL 1 YEAR DELETE;
CREATE TABLE users_rmt (id UInt64, name String, version UInt32) ENGINE = ReplacingMergeTree(version) ORDER BY id;
CREATE TABLE daily_sum (day Date, key String, total UInt64) ENGINE = SummingMergeTree ORDER BY (day, key);
CREATE TABLE daily_agg (day Date, key String, uniq_state AggregateFunction(uniq, UInt64), q_state AggregateFunction(quantile(0.9), Float64)) ENGINE = AggregatingMergeTree ORDER BY (day, key);
CREATE TABLE collapsing (id UInt64, sign Int8, v UInt32) ENGINE = CollapsingMergeTree(sign) ORDER BY id;
CREATE TABLE repl_events (ts DateTime, id UInt64) ENGINE = ReplicatedMergeTree('/clickhouse/tables/{shard}/repl_events', '{replica}') ORDER BY (id, ts);
CREATE TABLE dist_events AS local_events ENGINE = Distributed('my_cluster', 'default', 'local_events', rand());
CREATE TABLE IF NOT EXISTS lc_test (id UInt32, s LowCardinality(Nullable(String))) ENGINE = MergeTree ORDER BY id;
CREATE TABLE t_enum (id UInt32, status Enum8('new' = 1, 'paid' = 2, 'shipped' = 3)) ENGINE = MergeTree ORDER BY id;
CREATE TABLE t_defaults (id UInt64, created DateTime DEFAULT now(), day Date MATERIALIZED toDate(created), note String DEFAULT '' COMMENT 'free text', hash UInt64 ALIAS cityHash64(id)) ENGINE = MergeTree ORDER BY id;
CREATE TABLE t_idx (id UInt64, s String, INDEX idx_s s TYPE tokenbf_v1(10240, 3, 0) GRANULARITY 4, INDEX idx_id id TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY id;
CREATE TABLE t_nested (id UInt64, n Nested(k String, v UInt32)) ENGINE = MergeTree ORDER BY id;
CREATE TABLE t_log (msg String) ENGINE = Log;
CREATE TABLE t_mem (a UInt8) ENGINE = Memory;
CREATE TABLE t_sample (id UInt64, h UInt64) ENGINE = MergeTree ORDER BY (id, intHash32(h)) SAMPLE BY intHash32(h);
CREATE TABLE copy_of_events AS events;
CREATE TABLE t_from_select ENGINE = MergeTree ORDER BY id AS SELECT id, name FROM users;
CREATE DATABASE IF NOT EXISTS analytics;
CREATE DATABASE analytics ENGINE = Atomic;
DROP TABLE IF EXISTS tmp_staging;
DROP DATABASE IF EXISTS scratch;
RENAME TABLE old_events TO events_old, new_events TO old_events;
EXCHANGE TABLES a AND b;
ALTER TABLE events ADD COLUMN IF NOT EXISTS country LowCardinality(String) DEFAULT '' AFTER user_id;
ALTER TABLE events DROP COLUMN IF EXISTS legacy;
ALTER TABLE events MODIFY COLUMN name LowCardinality(String);
ALTER TABLE events RENAME COLUMN name TO event_name;
ALTER TABLE events COMMENT COLUMN event_name 'event type';
ALTER TABLE events MODIFY TTL ts + INTERVAL 6 MONTH;
ALTER TABLE events ADD INDEX idx_name event_name TYPE bloom_filter GRANULARITY 3;
ALTER TABLE events DROP INDEX idx_name;
ALTER TABLE events MATERIALIZE INDEX idx_name;
ALTER TABLE events ADD PROJECTION p_by_user (SELECT user_id, count() GROUP BY user_id);
ALTER TABLE events MODIFY SETTING ttl_only_drop_parts = 1;
ALTER TABLE events DROP PARTITION '202401';
ALTER TABLE events DROP PARTITION ID '20240101';
ALTER TABLE events DETACH PARTITION 202301;
ALTER TABLE events ATTACH PARTITION 202301;
ALTER TABLE events FREEZE PARTITION '2024-01-01';
ALTER TABLE events ON CLUSTER my_cluster ADD COLUMN x UInt8;
CREATE TABLE ddl_cluster ON CLUSTER my_cluster (id UInt64) ENGINE = MergeTree ORDER BY id;
OPTIMIZE TABLE events FINAL;
OPTIMIZE TABLE events PARTITION 202401 FINAL;
OPTIMIZE TABLE events DEDUPLICATE;
